from past.builtins import basestring
import io
import re
import logging
from collections import OrderedDict

import sys
if sys.version_info[0] == 3:
    import csv
else:
    import csv342 as csv

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class sherpa(object):
    """
    Class to manage a single csv generated files, useful for reading and manage content from Sherpa

    MANDATORY: read a file using setup_reader keyword before analysing, as shown in example below

    .. code-block:: robotframework

        Keyword 1
            [Documentation]     verify the presence of a given set of values in a csv file issued from sherpa traces
            ...                 return True if all of them are found, False if not
            [Arguments]             ${file}    ${Column_name}    ${valuetocheck}
            SherpaCsvReader.setup reader    ${file}
            ${result}     SherpaCsvReader.check all values for column    ${Column_name}    ${valuetocheck}
            [Return]    ${result}
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        """
        Build a dict reading a csv sherpa generated file

        :return: none
        """
        logger.warning(
            "The Sherpa(taf.analyzer.sherpa) library is deprecated as part of the phase-out of the Sherpa Tool and will"
            "be removed in a future release of the WebEm API.",
        )
        self._csv_file_path = None
        self._sherpa_dict_reader = None
        self._sherpa_list = []

    def setup_reader(self, file_path):
        """
        Read a csv file.
        The usage of this method is === MANDATORY === before doing anything on a csv file

        :param str file_path: file path of the csv file to be analysed
        :return: none
        """
        self._csv_file_path = file_path
        self._sherpa_list = []
        with io.open(self._csv_file_path, encoding='utf-8', newline='') as csvfile:
            self._sherpa_dict_reader = csv.DictReader(csvfile, delimiter=';')
            fieldnames = list(filter(None, self._sherpa_dict_reader.fieldnames))
            logging.info("FIELDNAMES:\n{}".format(fieldnames))
            for row in self._sherpa_dict_reader:
                self._sherpa_list.append(OrderedDict((k, row[k]) for k in fieldnames))

    def get_csv_size(self):
        """
        Get the number of rows in the CSV file

        :return: the number of rows in the CSV file
        """
        if self._sherpa_list:
            return len(self._sherpa_list)
        else:
            raise Exception("Internal list is empty")

    def get_csv_columns(self):
        """
        Get the column names of the sherpa csv file.

        :return: a list containing the column names
        """
        return self._sherpa_dict_reader.fieldnames[:-1]

    def get_values_for_column(self, column, regex_filter=None):
        """
        Get all the values for a given column from a sherpa csv file

        :param str column: the column name for which the values are demanded
        :param str regex_filter: filter regular expression to match rows
        :return: a list containing all the values for the given column (it may be empty)
        """
        values_list = [item[column] for item in self._sherpa_list
                       if regex_filter is None or re.search(regex_filter, item[column])]
        return values_list

    def get_rows_for_matching_column(self, column, regex_filter=None):
        """
        Get all the rows for a given column matching a regex from a sherpa csv file

        :param str column: the column name for which the filtering has to be applied
        :param str regex_filter: filter regular expression to match rows
        :return: a list containing all the rows filtered on the given column (it may be empty)
        """
        values_list = [item for item in self._sherpa_list
                       if regex_filter is None or re.search(regex_filter, item[column])]
        return values_list

    def check_all_values_for_column(self, column, values_list_tocheck):
        """
        Check a list of values in all the values for a given column from a sherpa csv file

        :param str column: the column for which the values have to be checked
        :param list values_list_tocheck: a list of values or a string to check
        :return: True if all the values are present, False if at least one is not present
        """
        if isinstance(values_list_tocheck, basestring):
            values_list_tocheck = [values_list_tocheck]
        values_list = self.get_values_for_column(column)
        result = set(values_list_tocheck) <= set(values_list)
        return result

    def check_csv_column_match_all(self, column, regex_tocheck):
        """
        Check that all values of a column match a regex
        :param str column: the column for which the values have to be checked
        :param str regex_tocheck: a regex to check on all the column values
        :return: True if all the values match the regex, False if at least one does not;
        the list of the column values
        """
        values_list = self.get_values_for_column(column)
        not_empty_list = bool(values_list)
        logging.debug("Column not empty: {}".format(not_empty_list))
        not_match = next((row for row in values_list if not re.search(regex_tocheck, row)), None)
        if not_match is not None:
            logging.debug("Not matching value: {}".format(not_match))
        return not_empty_list and not_match is None, values_list

    def check_csv_column_match_all_match_another(self, column, regex_condition, condition_column, regex_tocheck):
        """
        Check that all the csv values (filtered on another column) of a column match a regex
        :param str column: the column for which the values have to be checked
        :param str condition_column: a prerequisite column to which regex_condition applies
        :param str regex_condition: a condition filter on all the condition_column values
        :param str regex_tocheck: a regex to check on all the column values
        :return: True if all the conditioned values match the regex, False if at least one does not;
        the list of the column values
        """
        values = [
            row[column]
            for row in self._sherpa_list
            if re.search(regex_condition, row[condition_column])]
        matched = all(re.search(regex_tocheck, value) for value in values)
        logging.debug("conditioned list not empty: {}\n\nVALUES\n{}".format(matched, values))
        return matched, values

    def check_values_column_matching_regex_match_another(self, column, regex_condition, regex_tocheck):
        """
        Check that all the filtered values of a column match a regex

        :param str column: the column for which the values have to be checked
        :param str regex_condition: a condition filter on all the column values
        :param str regex_tocheck: a regex to check on all the column values for which filter is matched
        :return: True if all the filtered values match the regex_tocheck, False if at least one does not;
        the filtered value list
        """
        values_list = self.get_values_for_column(column, regex_condition)
        not_empty_list = bool(values_list)
        result = all(re.search(regex_tocheck, value) for value in values_list)
        return not_empty_list and result, values_list

    def check_rows_matching_regex_match_another(self, column, regex_condition, regex_tocheck):
        """
        Check that all the filtered rows filtered on a column match a regex

        :param str column: the column for which the rows have to be filtered
        :param str regex_condition: a condition filter on all the column values
        :param str regex_tocheck: a regex to check on all the rows for which filter is matched
        :return: True if all the filtered rows match the regex_tocheck, False if at least one does not;
        the filtered rows list
        """
        values_list = self.get_rows_for_matching_column(column, regex_condition)
        not_empty_list = bool(values_list)
        result = all(re.search(regex_tocheck, ";".join(list(value.values()))) for value in values_list)
        return not_empty_list and result, values_list

    def check_value_list_column_when_value(self, req_column, req_column_value, check_list_column, check_list):
        """
        Check that a list of values is present in all the rows matching the required value for a given column

        :param str req_column: the column for which the required value has to be checked
        :param str req_column_value: the value to be checked to filter the rows
        :param str check_list_column: the column in which the list of values have to be checked
        :param list check_list: values to be checked in the column for the filtered rows
        :return: True if all the values are present in the filtered rows, False if at least one is not present
                in at least one filtered row; the filtered value list
        """
        values_list = None
        if self._sherpa_list and len(self._sherpa_list) >= 1:
            values_list = [
                (item[check_list_column]) for item in self._sherpa_list
                if item[req_column] == req_column_value
            ]
        result = bool(values_list)
        logging.debug("\nres after list first check: {}".format(result))
        not_match = next((value for value in values_list if not all(elem in value for elem in check_list)), None)
        if not_match is not None:
            logging.debug("Not matching value: {}".format(not_match))
        return result and not_match is None, values_list

    def print_all(self):
        """
        Just a tool method that prints the content of the internal dictionary generated from a sherpa csv file
        """
        if self._sherpa_list:
            try:
                for row in self._sherpa_list:
                    print(row)
            except Exception:
                raise Exception("error reading list: {})".format(self._sherpa_list))
        else:
            raise Exception("Internal list is empty")
